update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p101","body":"ابھی دل کے شجر پہ کوئی ثمر نہیں\nنہ کوئی سایہ جو اور دور تک کوئی شجر نہیں\nنہ کسی قسم کی خزاں کا خوف باقی ہے\nاور بہاروں کے آ جانے کا بھی کوئی اثر نہیں\nنہ کوئی چنچلاتی آوازوں کا شور ہے\nنہ  سانسیں لیتی ہوئی گھپ تنہائی ہے\nنہ یادوں کے ٹھاٹھے مارتے ہوئے طوفاں ہیں\nنہ ملالوں کی گرجتی ہوئی دہائی ہے\nہو سکے گا تو بلا لیں گے ان پرانی رتوں کو\nجن کے ہوتے ہوئے ہم بھی کھلا کرتے تھے\nزندگی جن کے تصور میں یونہی کاٹ کر\nحقیقت میں جنھیں خود سے جدا کرتے تھے\nوہ لوگ ،  وہ شجر اب کہاں ہیں؟\nاب تو ان کا کہیں سایہ و ہجم بھی نہیں\nکئی کو زمین نگل گئی کئی کو آسماں کھا گیا\nایک ہم بچ گئے اور پھر ہم بھی نہیں"},{"slug":"tum-p102","body":"تم سے بچھڑ کے میں ، آخر  سنبھل  گیا ہوں\nاک بار پھر کچے آسرے سے ٹل  گیا ہوں\nیہ جانتے ہوئے کہ تم کیا خاک سنبھالو گے\nٹوٹا سا دل مرا پھر سے توڑ ڈالو گے\nمیں نے تم پہ یقین کر لیا تھا\nخود خسارہ اپنے سر لیا تھا\nتم کہ جھونکتے رہے دھول آنکھوں میں\nہم نے رواں رکھا تمہیں اپنی سانسوں میں\nخیر اس میں میرا ہی قصور ہے\nمجھ سے وفا بہت دور ہے\nمیں نے ہی تو تمہیں اس آزمائش میں ڈالا تھا\nہمیشہ زمانے کی گردشوں سے سنبھالا تھا\nمجھے یوں مخلص نہیں ہونا چاہیے تھا\nیوں تم سا شخص نہیں کھونا چایئے تھا\nپر تم جانتی ہو میں کبھی سوال  نہیں رکھتا\nدل میں کوئی بھی  ملال نہیں رکھتا\nجانتا ہوں تمارے جواب پہلے سے\nدل پہ اترتا رہا ہے یہ عذاب پہلے سے\nپھر سے کر کے اندھا اعتماد ، میں بہل جاوں گا\nاس بار بھی پہلے کی طرح  میں سنبھل جاوں گا\nخوش رہنا ، تم میری فکر مت کرنا\nکسی کے سامنے میرا زکر مت کرنا\nاپنی زندگی کو گزارنا نہیں بلکہ جیون کرنا\nاک طرف رہنا، کسی کی زندگی نہ اجیرن کرنا\nمیں آئندہ دو دلوں کے بیچ نہیں آوں گا\nمیں اب امید ہے یہ بات جان جاوں گا\nجان جاوں گا یہ خسارے کہاں سے آتے ہیں\nہم گرنے والوں کو سہارے کہاں سے آتے ہیں؟"},{"slug":"tum-p103","body":"یونہی ٹرین کی برتھ پر لیٹے لیٹے\nتیری یادوں کے ہم نے قصے چھیڑے\nاس سفر میں دن گیا اس سفر میں رات ڈھلے\nوقت کی رفتار سے بھی اکثر ہم تم تھے تیز چلے\nتم نے وعدہ کیا تھا آنے کا\nاور  نہ آنے کے بہانے ہم نے بوجھے\nہر سو گونجتی چنچلاتی آوازوں میں\nایک تری آواز کے نغمے ڈھونڈے\nشام سویرے یادوں کی تیز ژالہ باری میں\nچھت تلے کھڑے تھے ہم ، پھر بھی مگر بھیگ گئے\nکام نہ تھا کوئی ، بیٹھے تھے یاروں کی محفل میں\nدل جلا تو اٹھ چلے ، پھر یار ملے نہ تم ملے\nبے سر و سامان چلے تھے ہم محبت کی اک نگری میں\nایک دل لیے نکلے تھے ، وہ دل بھی کہیں پہ بھول گئے\nیاس و حرماں کی داستاں میں ، انا پرست ایک کہانی میں\nاحمد ؔ ملنا لکھا تھا قسمت میں ، پر ملتے ملتے بچھڑ گئے"},{"slug":"tum-p104","body":"دو پل کو یہ پنچھی بھی ٹھہر جائینگے\nموقع ملنے کی دیر ہے پھر اڑ جائینگے\n\nزندگی تیرے تسلسل سے ہوگیا ہوں واقف\nلوگ یہاں ملیں گے پھر آخر بچھڑ جائینگے\n\nتو بھی ضروری سے ہوگیا معمولی\nہم بھی کل دل سے اتر جائینگے\n\nشب ہجر ہوئے داغ ماہتاب نمایاں\nصبح ہونے تک یہ بھی بھر جائینگے\n\nاحمد ؔ ہم ہرگز نہ لکھتے اگر ہوتی خبر\nیہ شعر بھی باتوں کی طرح بے اثر جائینگے"},{"slug":"tum-p105","body":"تیرا چہرہ بھی جفت ہے\nبالکل زمانے کی طرح\nتیری آنکھیں بھی دیکھتی رہیں\nکسی انجانے کی طرح\n\nاب بھی گواہ ہے دل تیرا\nکہ میں نے تجھ سے محبت کی ہے\nحقیقتوں میں ، چاہے افسانوں میں\nتیری ہی جانب حرکت کی ہے\n\nاب جانے کیوں یوں لگتا ہے\nتو کچھ بھی نہیں، بس اک خیال ہے\nایک تو ہے کہ کیا سے کیا ہو گیا\nایک میں ہوں مجھے اسکا بھی ملال ہے\n\nمگر سوچتا ہوں میری کہانی میں\nتیری آخر کیا روش رہی ہے\nوصل میں بچھڑنے کی\nتیری اکثر کوشش رہی ہے\n\nسوچتا ہوں کہ تو بس ایک چنگاری تھی\nمیں ہی فقط ایندھن تھا\nجسے نور قمر سمجھتا رہا تھا\nوہ دل آتش شمس میں روشن تھا\n\nمیں نے ہی ہجوم سے تجھے چنا تھا\nتو نے اشارے سے سدا دی تھی مجھے\nمیں خود ہی جل گیا تھا\nتو نے تو بس ہوا دی تھی مجھے\n\nتیرے وجود نے\nاور تو کچھ نہیں کیا\nسوائے اس کے کہ\nمجھے موضوع دیا\n\nلکھنے کا ، پرکھنے کا ، زندگی کا ، تلخی کا\nجستجو کا ، آرزو کا، اپنائیت کا، حیوانیت کا\nفقط تیرا ہر پہلو اب لکھ چکا ہوں میں\nمجھے آزاد کر دے ،  تھک چکا ہوں میں"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
